  Ptr<Packet> tmp = payload->Copy ();
  CsrNetHeader nh;
  if (tmp->PeekHeader (nh))
  {
    sendDack = m_shouldDackCb (nh.GetSrc (), nh.GetDst ());
  }
}

auto deliverToNwk = [&] () {
  if (firstReception && !m_rxFromHopCb.IsNull ())
