CsrMacCore::EnqueueTxFrame (Ptr<Packet> frame,
                            CsrNodeId dest,
                            uint8_t dscp,
                            bool ackable)
{
  CsrAnnotateOpnetEnvelope (frame);

  CsrHeader header;
  if (frame != nullptr && frame->PeekHeader (header) &&
      (header.IsAck () || header.IsDack () ||
       header.GetType () == CSR_PKT_ACK ||
       header.GetType () == CSR_PKT_DACK))
    {
      EnqueueAckFrame (frame, header);
      return;
    }

for (auto &entry : selected)
  {
    CsrHeader header;
    entry.frame->RemoveHeader (header);
    if (header.HasLinkControl ())
      {
        header.SetLinkControl (
          static_cast<CsrRateKey> (aggregateRateKbps),
          aggregateTxPowerDbm,
          header.GetRxPowerDbm ());
      }
    else
      {
        header.SetSpeedKey (aggregateRateKbps);
      }
    if (header.GetType () == CSR_PKT_DATA ||
        header.GetType () == CSR_PKT_ACK ||
        header.GetType () == CSR_PKT_DACK)
      {
        header.SetType (header.IsAck ()
                          ? CSR_PKT_ACK
                          : (header.IsDack ()
                               ? CSR_PKT_DACK
                               : CSR_PKT_DATA));
      }
    header.SetDestType (
      header.HasDestinationSequences ()
        ? CSR_DEST_MULTICAST
        : (entry.dest == CSR_BROADCAST_ID
             ? CSR_DEST_BROADCAST
             : CSR_DEST_UNICAST));
    entry.frame->AddHeader (header);
    wireFrames.push_back (entry.frame);
    anyAckable = anyAckable || entry.ackable;
  }

if (hdr.IsAck () ||
    hdr.GetType () == CSR_PKT_ACK ||
    hdr.GetType () == CSR_PKT_DACK)
  {
    if (!AuthenticateAckFrame (hdr, frame))
      {
        return;
      }

    std::cout << "[HOP " << m_nodeId << "] RX "
              << (hdr.IsDack () ? "DACK" : "ACK")
              << " from " << hdr.GetSrc ()
              << " seq=" << hdr.GetSeq () << std::endl;

    if (hdr.HasAckWindow ())
      {
        HandleAckWindow (hdr);
      }
    else if (hdr.IsDack ())
      {
        // The recovered source hard-disables its legacy single-DACK block,
        // and the exact-sequence fallback is guarded to ACK only.  A
        // non-window DACK is therefore a custody/MAC no-op, while the
        // packet-level generic wake below still runs.
      }
    else
      {
        ResendEntry *ackEntry =
          FindResendEntry (hdr.GetSrc (), hdr.GetSeq ());
        const bool dataCompletion =
          ackEntry != nullptr && ackEntry->flowControlTracked;

        // Keep this branch bounded to ordinary DATA.  Reliable-control
        // callbacks already observe MAC cancellation first in the
        // synchronous model; changing them would be unrelated collateral.
        if (!dataCompletion)
          {
            m_mac->CancelAcknowledgedFrames (
              hdr.GetSrc (), hdr.GetSeq (), 1, 0);
          }

        HandleAckFrame (hdr);

        // The legacy Ack_Inst is posted before HOP completion but handled by
        // br_mac only after br_hop yields.  For DATA, apply the synchronous
        // equivalent after HOP flow/NSDP release and resend removal.
        if (dataCompletion)
          {
            m_mac->CancelAcknowledgedFrames (
              hdr.GetSrc (), hdr.GetSeq (), 1, 0);
          }
      }

    // Legacy br_hop schedules this remote interrupt after every readable,
    // locally addressed ACK/DACK packet.  The wake is required even when
    // every sequence is unknown, stale, duplicated, or otherwise produces
    // no resend/flow-control state change.
    ScheduleNwkQueueWake ();

CsrHopLayer::HandleAckWindow (const CsrHeader &hdr)
{
  CsrNodeId src = hdr.GetSrc ();
  uint16_t baseSeq = hdr.GetSeq ();

  // The br_hop proc_mac_pk() cumulative-feedback path evaluates the ACK
  // register before the DACK register.  If both contain the same sequence,
  // the ACK path completes it and the later DACK lookup no longer finds an
  // outstanding entry.
  uint64_t ackBitmap = hdr.GetAckBitmap ();
  uint64_t dackBitmap = hdr.GetDackBitmap () & ~ackBitmap;

  for (uint32_t bit = 0; bit < 64; ++bit)
    {
      uint64_t mask = 1ULL << bit;
      bool isDack = (dackBitmap & mask) != 0;

      if (!isDack && (ackBitmap & mask) == 0)
        {
          continue;
        }

      CsrHeader completed = hdr;
      completed.SetSeq (static_cast<uint16_t> (baseSeq - bit));
      completed.SetHasAckWindow (false);
      completed.SetAckBitmap (0);
      completed.SetDackBitmap (0);
      completed.SetIsDack (isDack);
      completed.SetType (isDack ? CSR_PKT_DACK : CSR_PKT_ACK);

      if (isDack)
        {
          HandleDackFrame (completed);
        }
      else
        {
          HandleAckFrame (completed);
        }
    }

  // br_hop posts one br_Mac_Hop_Inst before scanning the cumulative maps, but
  // br_mac cannot handle that stream event until the current HOP event yields.
  // Complete every HOP/NSDP/resend mutation first, then apply the equivalent
  // queued-copy cancellation at MAC.
  m_mac->CancelAcknowledgedFrames (
    src, baseSeq, ackBitmap, dackBitmap);
}

virtual void Serialize (Buffer::Iterator start) const override
{
  uint8_t flags = 0;
  if (m_ackable) { flags |= 0x01; }
  if (m_isAck)   { flags |= 0x02; }
  if (m_isDack)  { flags |= 0x04; }
  if (m_hasAckWindow) { flags |= 0x08; }
  if (!m_destinationSequences.empty ()) { flags |= 0x10; }
  if (m_hasLinkControl) { flags |= 0x20; }
  if (m_hasSecurityCount) { flags |= 0x40; }
  if (m_hasGroupSecurity) { flags |= 0x80; }

  CsrWriteNodeId (start, m_src);
  CsrWriteNodeId (start, m_dst);
  start.WriteHtonU16 (m_seq);
  start.WriteU8 (m_dscp);
  start.WriteU8 (flags);
  start.WriteU8 (m_type);
  start.WriteU8 (m_destType);
  start.WriteU8 (m_speedKey);

  if (m_hasAckWindow)
    {
      start.WriteHtonU64 (m_ackBitmap);
      start.WriteHtonU64 (m_dackBitmap);
    }

  if (m_hasLinkControl)
    {
      start.WriteHtonU16 (
        static_cast<uint16_t> (m_txPowerDbmX10));
      start.WriteHtonU16 (
        static_cast<uint16_t> (m_rxPowerDbmX10));
    }
